#include <math.h>

MagickBooleanType ComputeBezierCurve(void)
{
  size_t
    i;

  PointInfo
    *points;

  double
    *coefficients,
    t,
    t_squared,
    t_cubed,
    one_minus_t,
    one_minus_t_squared,
    one_minus_t_cubed;

  MagickBooleanType
    status;

  size_t
    num_segments;

  PointInfo
    control_points[4];

  points = (PointInfo *) AcquireQuantumMemory(4, sizeof(*points));
  if (points == (PointInfo *) NULL)
    {
      (void) ThrowMagickException(NULL, GetMagickModule(), ResourceLimitError,
        "UnableToAcquireMemory", "Memory allocation failed for Bezier points");
      return MagickFalse;
    }

  coefficients = (double *) AcquireQuantumMemory(4, sizeof(*coefficients));
  if (coefficients == (double *) NULL)
    {
      RelinquishMemory(points);
      (void) ThrowMagickException(NULL, GetMagickModule(), ResourceLimitError,
        "UnableToAcquireMemory", "Memory allocation failed for Bezier coefficients");
      return MagickFalse;
    }

  for (i = 0; i < 4; i++)
  {
    control_points[i].x = cos(i * 90.0);
    control_points[i].y = sin(i * 90.0);
  }

  for (t = 0.0; t <= 1.0; t += 0.1)
  {
    t_squared = t * t;
    t_cubed = t * t_squared;
    one_minus_t = 1.0 - t;
    one_minus_t_squared = one_minus_t * one_minus_t;
    one_minus_t_cubed = one_minus_t * one_minus_t_squared;

    points[0].x = one_minus_t_cubed * control_points[0].x;
    points[0].x += 3.0 * t * one_minus_t_squared * control_points[1].x;
    points[0].x += 3.0 * t_squared * one_minus_t * control_points[2].x;
    points[0].x += t_cubed * control_points[3].x;

    points[0].y = one_minus_t_cubed * control_points[0].y;
    points[0].y += 3.0 * t * one_minus_t_squared * control_points[1].y;
    points[0].y += 3.0 * t_squared * one_minus_t * control_points[2].y;
    points[0].y += t_cubed * control_points[3].y;

    if (t == 1.0)
      points[0] = control_points[3];
  }

  if (!ValidatePrimitive(points))
  {
    RelinquishMemory(points);
    RelinquishMemory(coefficients);
    return MagickFalse;
  }

  RelinquishMemory(coefficients);
  return MagickTrue;
}

#include <math.h>
#include <stdlib.h>

MagickBooleanType TraceBezier(void)
{
  Coefficient *coefficients = (Coefficient *) AcquireQuantumMemory(4, sizeof(*coefficients));
  Point *points = (Point *) AcquireQuantumMemory(4, sizeof(*points));
  MagickBooleanType status = MagickTrue;

  if ((coefficients == (Coefficient *) NULL) || (points == (Point *) NULL))
  {
    status = MagickFalse;
    ThrowBinaryException(ResourceLimitError, "UnableToAllocateBezierMemory", " ");
  }

  for (int i = 0; i < 4; i++)
  {
    double t = (double) i / 3.0;
    coefficients[i] = (1.0 - t) * t * t * t;
  }

  for (int i = 0; i < 4; i++)
  {
    double angle = 2.0 * M_PI * (double) i / 3.0;
    points[i].x = cos(angle);
    points[i].y = sin(angle);
  }

  if (status == MagickTrue)
  {
    double weight = 1.0;
    for (int i = 0; i < 4; i++)
    {
      points[i].x *= weight * coefficients[i];
      points[i].y *= weight * coefficients[i];
      weight *= 0.9;
    }
  }

  if (status == MagickTrue)
  {
    double x = 0.0;
    double y = 0.0;
    for (int i = 0; i < 4; i++)
    {
      x += points[i].x;
      y += points[i].y;
    }
    if ((fabs(x) > QuantumRange) || (fabs(y) > QuantumRange))
      status = MagickFalse;
  }

  if (status == MagickFalse)
  {
    if (coefficients != (Coefficient *) NULL)
      coefficients = (Coefficient *) RelinquishMagickMemory(coefficients);
    if (points != (Point *) NULL)
      points = (Point *) RelinquishMagickMemory(points);
    ThrowBinaryException(ResourceLimitError, "BezierPrimitiveExceedsExtent", " ");
  }

  return(status);
}

#include <math.h>
