    if ( points == NULL )
    {
        status = MagickFalse;
        goto cleanup;
    }

    for ( int i = 0; i < 100; i++ )
    {
        double t = (double)i / 99.0;
        double oneMinusT = 1.0 - t;
        coefficients[0] = oneMinusT * oneMinusT * oneMinusT;
        coefficients[1] = 3.0 * t * oneMinusT * oneMinusT;
        coefficients[2] = 3.0 * t * t * oneMinusT;
        coefficients[3] = t * t * t;

        double x = 0.0;
        double y = 0.0;

        for ( int j = 0; j < 4; j++ )
        {
            x += coefficients[j] * controlPoints[j].x;
            y += coefficients[j] * controlPoints[j].y;
        }

        points[i].x = x;
        points[i].y = y;
    }

    if ( !CheckPrimitiveExtent( points, 100 ) )
    {
        status = MagickFalse;
        goto cleanup;
    }

